import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import "./ProductDetails.css";
import productData from "../data/product.json";

function ProductDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const product = productData.find(item => item.id === parseInt(id));

  // Debugging: Check if product and image path are correct
  console.log("Product found:", product);
  if (product) {
    console.log("Image path:", product.image);
  }

  if (!product) {
    navigate("/categories");
    return null;
  }

  const formatPrice = (price) => {
    return `₱${price.toLocaleString()}`;
  };

  return (
    <div className="product-details-container">
      <div className="product-details-card">
        {/* Product Image Section */}
        <div className="product-image-section">
          <div className="product-image-container">
           <img 
            src={product.image} 
            alt={product.name}
            className="product-detail-image"
            onError={(e) => {
                e.target.src = process.env.PUBLIC_URL + "public/images";
            }}
            />
          </div>
        </div>

        {/* Rest of your component remains the same */}
        <div className="product-info-section">
          <div className="item-name">{product.name}</div>
          <div className="price-text">PRICE</div>
          <div className="price-amount">{formatPrice(product.price)}</div>
          <div className="product-details-text">PRODUCT DETAILS</div>
          <p className="product-description">{product.description}</p>
          <div className="divider"></div>
          <div className="action-buttons">
            <button className="add-to-cart-btn">ADD TO CART</button>
            <button className="buy-now-btn">BUY NOW</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default ProductDetails;
